const express = require("express");
const cors = require("cors");
const app = express();

// แบบ 1: ใช้ package cors
app.use(cors({
  origin: ["http://localhost:3100"],
  methods: "GET,POST,PUT,DELETE"
}));

// แบบ 2: ตั้ง header เอง
app.use((req, res, next) => {
  res.header("Access-Control-Allow-Origin", "http://localhost:3100");
  res.header("Access-Control-Allow-Methods", "GET,POST,PUT,DELETE");
  res.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
  next();
});

const token = localStorage.getItem("token");

function addStudent(student) {
  fetch("http://localhost:3000/student", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": "Bearer " + token
    },
    body: JSON.stringify({ student: student })
  })
    .then(res => res.json())
    .then(data => console.log(data.message))
    .catch(err => console.log(err));
}

// axios
function addStudentAxios(student) {
  axios.post("http://localhost:3000/student", { student }, {
    headers: { Authorization: "Bearer " + token }
  })
    .then(res => console.log(res.data.message))   // axios แปลง JSON ให้แล้ว
    .catch(err => console.log(err));
}
